-- Publicação inicial dos documentos jurídicos aprovados.
-- Conteúdo codificado em Base64 para preservar exatamente os bytes UTF-8.

INSERT INTO identity_legalDocumentVersion
  (documentType, versionName, required, content, contentHash, effectiveAt, retiredAt)
SELECT 'TERMS_OF_USE', '1.0.0', TRUE,
       CONVERT(FROM_BASE64('') USING utf8mb4),
       UNHEX('44ABC3D11826EAE8DCCC8272229BB94657300C1632AFAB91C28F4B3D7D551570'),
       CURRENT_TIMESTAMP(6), NULL
WHERE NOT EXISTS (
  SELECT 1 FROM identity_legalDocumentVersion
  WHERE documentType = 'TERMS_OF_USE' AND versionName = '1.0.0'
);

INSERT INTO identity_legalDocumentVersion
  (documentType, versionName, required, content, contentHash, effectiveAt, retiredAt)
SELECT 'PRIVACY_POLICY', '1.0.0', TRUE,
       CONVERT(FROM_BASE64('') USING utf8mb4),
       UNHEX('33D468F0C3E0016C2376BA3299585EA11F02919B9400903C8D11114F48F076A9'),
       CURRENT_TIMESTAMP(6), NULL
WHERE NOT EXISTS (
  SELECT 1 FROM identity_legalDocumentVersion
  WHERE documentType = 'PRIVACY_POLICY' AND versionName = '1.0.0'
);

CREATE OR REPLACE
SQL SECURITY INVOKER
VIEW databaseVersion AS
SELECT '20260812001' AS version;
